// obs = {pos:[x,y,z], vel:[..], euler:[roll,pitch,yaw], rates:[..], alt}
// t = seconds. Return [roll, pitch, yaw_rate, throttle] (throttle 0..1).
function control(obs, t) {
  const target = 5.0;                     // hold 5 m
  let thr = 0.33 + 0.15 * (target - obs.alt) - 0.05 * obs.vel[1];
  return [0, 0, 0, Math.max(0, Math.min(1, thr))];
}
